/*
 * Read-side regression tests for fixed-width tar header parsing.
 *
 * Every case builds a raw 512-byte header directly and computes the
 * checksum independently of the library under test, so the corpus is not
 * generated by the writer being tested.
 */

#include "microtar.h"

#include <stdio.h>
#include <string.h>

static unsigned char raw[512];
static int failures;

#define CHECK(cond) do {                                                  \
    if (!(cond)) {                                                        \
      printf("FAIL %s:%d: %s\n", __FILE__, __LINE__, #cond);              \
      failures++;                                                         \
    }                                                                     \
  } while (0)

static int rd(mtar_t *t, void *p, unsigned n) {
  if (t->pos > sizeof raw || n > sizeof raw - t->pos) {
    return MTAR_EREADFAIL;
  }
  memcpy(p, raw + t->pos, n);
  return 0;
}

static int sk(mtar_t *t, unsigned p) {
  (void) t;
  return p <= sizeof raw ? 0 : MTAR_ESEEKFAIL;
}

/* Recompute the checksum from scratch and store it in the standard
 * "NNNNNN\0 " format */
static void fix_checksum(void) {
  unsigned sum = 0;
  unsigned i;
  memset(raw + 148, ' ', 8);
  for (i = 0; i < sizeof raw; i++) {
    sum += raw[i];
  }
  snprintf((char*) raw + 148, 8, "%06o", sum);
  raw[155] = ' ';
}

/* A minimal valid header for a regular empty file named "ok" */
static void mkvalid(void) {
  memset(raw, 0, sizeof raw);
  memcpy(raw, "ok", 2);
  memcpy(raw + 100, "0000644", 7);
  memcpy(raw + 108, "0000000", 7);
  memcpy(raw + 116, "0000000", 7);
  memcpy(raw + 124, "00000000000", 11);
  memcpy(raw + 136, "00000000000", 11);
  raw[156] = '0';
  fix_checksum();
}

static int read_header(mtar_header_t *h) {
  mtar_t t;
  memset(&t, 0, sizeof t);
  t.read = rd;
  t.seek = sk;
  return mtar_read_header(&t, h);
}

int main(void) {
  mtar_header_t h;
  int err;

  /* Baseline: a normal header still parses */
  mkvalid();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS);
  CHECK(!strcmp(h.name, "ok") && h.size == 0 && h.mode == 0644);

  /* The original crash layout: linkname filled with non-zero bytes up to
   * the end of the block. Must now return a negative error, not crash */
  mkvalid();
  memset(raw + 157, 'L', sizeof raw - 157);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* Name of length 0 (empty name field) is accepted */
  mkvalid();
  memset(raw, 0, 100);
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && h.name[0] == '\0');

  /* Name of 99 bytes plus terminator: the longest representable name */
  mkvalid();
  memset(raw, 'a', 99);
  raw[99] = '\0';
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && strlen(h.name) == 99);

  /* Name of 100 bytes with no terminator: must be rejected, not
   * truncated into a different name */
  mkvalid();
  memset(raw, 'a', 100);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* Linkname of 99 bytes plus terminator is accepted */
  mkvalid();
  memset(raw + 157, 'b', 99);
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && strlen(h.linkname) == 99);

  /* Bad digit hard against the next field: the 8th byte of mode is '8',
   * with no terminator or padding before the owner field */
  mkvalid();
  memcpy(raw + 100, "00006448", 8);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* Non-octal garbage at the field boundary */
  mkvalid();
  memcpy(raw + 100, "0000644X", 8);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* A sign is not a digit */
  mkvalid();
  memcpy(raw + 100, "-000644", 7);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* No digits at all */
  mkvalid();
  memset(raw + 100, ' ', 8);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* Leading spaces and trailing space padding are fine */
  mkvalid();
  memcpy(raw + 100, "  0644 ", 7);
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && h.mode == 0644);

  /* Largest value representable in the 12-byte size field: UINT_MAX */
  mkvalid();
  memcpy(raw + 124, "37777777777", 11);
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && h.size == 0xFFFFFFFFu);

  /* One past UINT_MAX: unsigned overflow must be rejected */
  mkvalid();
  memcpy(raw + 124, "40000000000", 11);
  fix_checksum();
  err = read_header(&h);
  CHECK(err < 0);

  /* Largest value representable in the 8-byte mode field */
  mkvalid();
  memcpy(raw + 100, "7777777", 7);
  fix_checksum();
  err = read_header(&h);
  CHECK(err == MTAR_ESUCCESS && h.mode == 007777777);

  /* All-zero block: the real end-of-archive marker */
  memset(raw, 0, sizeof raw);
  err = read_header(&h);
  CHECK(err == MTAR_ENULLRECORD);

  /* Pseudo end-of-archive: non-zero block whose checksum field starts
   * with a null byte. Must not be reported as a null record */
  mkvalid();
  memset(raw + 148, 0, 8);
  err = read_header(&h);
  CHECK(err < 0 && err != MTAR_ENULLRECORD);

  /* Same idea, almost-empty block with only a name byte set */
  memset(raw, 0, sizeof raw);
  raw[0] = 'x';
  err = read_header(&h);
  CHECK(err < 0 && err != MTAR_ENULLRECORD);

  /* Well-formed checksum field, wrong value */
  mkvalid();
  raw[0] = 'O';
  err = read_header(&h);
  CHECK(err == MTAR_EBADCHKSUM);

  if (failures) {
    printf("header read tests: %d failure(s)\n", failures);
    return 1;
  }
  puts("header read tests PASS");
  return 0;
}
